#!/bin/bash
# NodeJS App Installation Script
#
# Server Files: /mnt/server
apt update
apt install -y git curl jq file unzip make gcc g++ python3 python3-dev python3-pip libtool

echo -e "updating npm. please wait..."
npm install npm@latest --location=global

mkdir -p /mnt/server
cd /mnt/server

if [ "${USER_UPLOAD}" == "true" ] || [ "${USER_UPLOAD}" == "1" ]; then
    echo -e "assuming user knows what they are doing have a good day."
    exit 0
fi

## Plantilla de Cinammon (TypeScript): servidor vacío y sin repositorio -> bot de Discord en TypeScript
if [ -z "${GIT_ADDRESS}" ] && [ -z "$(ls -A /mnt/server 2>/dev/null)" ]; then
    cd /mnt/server
    echo "Servidor vacío y sin repositorio: instalando la plantilla de bot de Discord en TypeScript de Cinammon"
    mkdir -p src
    cat > package.json <<'CINEOF'
{
  "name": "bot-discord-ts",
  "version": "1.0.0",
  "description": "Bot de Discord en TypeScript - plantilla de Cinammon",
  "private": true,
  "type": "module",
  "main": "dist/index.js",
  "scripts": { "build": "tsc", "start": "node dist/index.js" },
  "dependencies": { "discord.js": "^14.16.3" },
  "devDependencies": { "typescript": "^5.6.3", "@types/node": "^22.9.0" }
}
CINEOF
    cat > tsconfig.json <<'CINEOF'
{
  "compilerOptions": {
    "target": "ES2022",
    "module": "NodeNext",
    "moduleResolution": "NodeNext",
    "outDir": "./dist",
    "rootDir": "./src",
    "strict": true,
    "esModuleInterop": true,
    "skipLibCheck": true
  },
  "include": ["src/**/*"]
}
CINEOF
    cat > src/index.ts <<'CINEOF'
/**
 * Bot de Discord en TypeScript · plantilla de Cinammon
 *
 * Edita los archivos de src/ (por SFTP o desde Archivos) y reinicia: el servidor compila solo a dist/.
 * Token: pégalo en "Conexión con Discord" de la consola del panel (o pon DISCORD_TOKEN).
 */
import fs from 'node:fs';
import { Client, GatewayIntentBits, REST, Routes, SlashCommandBuilder, ChatInputCommandInteraction } from 'discord.js';

type Comando = { data: SlashCommandBuilder; run: (i: ChatInputCommandInteraction) => Promise<unknown> };

const COMANDOS: Comando[] = [
    { data: new SlashCommandBuilder().setName('ping').setDescription('Comprueba que el bot responde'),
      run: (i) => i.reply({ content: `Pong. Latencia: ${Math.round(i.client.ws.ping)} ms`, ephemeral: true }) },
    { data: new SlashCommandBuilder().setName('ayuda').setDescription('Lista de comandos'),
      run: (i) => i.reply({ content: COMANDOS.map((c) => `**/${c.data.name}** · ${c.data.description}`).join('\n'), ephemeral: true }) },
];

function config(): { token?: string; guild_id?: string } {
    try { return JSON.parse(fs.readFileSync('bot-config.json', 'utf8')); } catch { return {}; }
}

const cfg = config();
const token = String(cfg.token || process.env.DISCORD_TOKEN || '').trim();
if (!token) {
    console.log('Falta el token. Pégalo en el recuadro "Conexión con Discord" de la consola y el bot se reiniciará solo.');
    setInterval(() => {}, 60_000);
} else {
    const client = new Client({ intents: [GatewayIntentBits.Guilds] });
    client.once('ready', async (c) => {
        console.log(`Conectado como ${c.user.tag} en ${c.guilds.cache.size} servidor(es). [READY]`);
        const rest = new REST().setToken(token);
        const body = COMANDOS.map((x) => x.data.toJSON());
        const guild = String(cfg.guild_id || process.env.GUILD_ID || '').trim();
        await rest.put(guild ? Routes.applicationGuildCommands(c.user.id, guild) : Routes.applicationCommands(c.user.id), { body })
            .catch((e: Error) => console.log(`No se pudieron registrar los comandos: ${e.message}`));
    });
    client.on('interactionCreate', async (i) => {
        if (!i.isChatInputCommand()) return;
        const cmd = COMANDOS.find((x) => x.data.name === i.commandName);
        if (cmd) await cmd.run(i).catch((e: Error) => console.log(`/${i.commandName}: ${e.message}`));
    });
    client.login(token).catch((e: Error) => console.log(`El token no es válido o no se pudo conectar: ${e.message}`));
}
CINEOF
    npm install --include=dev
    npx tsc -p tsconfig.json || true
    echo "Plantilla TypeScript instalada. Edita src/index.ts y reinicia: se compila solo."
    exit 0
fi

## add git ending if it's not on the address
if [[ ${GIT_ADDRESS} != *.git ]]; then
    GIT_ADDRESS=${GIT_ADDRESS}.git
fi

if [ -z "${USERNAME}" ] && [ -z "${ACCESS_TOKEN}" ]; then
    echo -e "using anon api call"
else
    GIT_ADDRESS="https://${USERNAME}:${ACCESS_TOKEN}@$(echo -e ${GIT_ADDRESS} | cut -d/ -f3-)"
fi

## pull git js repo
if [ "$(ls -A /mnt/server)" ]; then
    echo -e "/mnt/server directory is not empty."
    if [ -d .git ]; then
        echo -e ".git directory exists"
        if [ -f .git/config ]; then
            echo -e "loading info from git config"
            ORIGIN=$(git config --get remote.origin.url)
        else
            echo -e "files found with no git config"
            echo -e "closing out without touching things to not break anything"
            exit 10
        fi
    fi

    if [ "${ORIGIN}" == "${GIT_ADDRESS}" ]; then
        echo "pulling latest from github"
        git pull
    fi
else
    echo -e "/mnt/server is empty.\ncloning files into repo"
    if [ -z ${BRANCH} ]; then
        echo -e "cloning default branch"
        git clone ${GIT_ADDRESS} .
    else
        echo -e "cloning ${BRANCH}'"
        git clone --single-branch --branch ${BRANCH} ${GIT_ADDRESS} .
    fi

fi

echo "Installing nodejs packages"
if [[ ! -z ${NODE_PACKAGES} ]]; then
    /usr/local/bin/npm install ${NODE_PACKAGES}
fi

if [ -f /mnt/server/package.json ]; then
    /usr/local/bin/npm install --production
fi

echo -e "install complete"
exit 0
